INSERT INTO homepage_sections (section_key, title, subtitle, content, settings_json, sort_order, is_visible) VALUES
('hero', 'Spaces That Feel Like You.', 'Thoughtfully designed interiors that bring together functionality, aesthetics, and the way you live.', '', '{"desktop_image":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=2000&q=85","mobile_image":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1080&q=85","focal_point_x":50,"focal_point_y":50,"cta_primary_text":"EXPLORE OUR PROJECTS","cta_primary_url":"/projects","cta_secondary_text":"LET\'S DISCUSS YOUR SPACE","cta_secondary_url":"/contact"}', 1, 1),
('brand_intro', 'Design That Goes Beyond the Surface.', 'At WROP Interior, every space begins with an idea. We bring together thoughtful planning, carefully considered materials, and a distinctive design approach to create spaces that feel personal and purposeful.', '', '{"image":"https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1400&q=85","badge":"EDITORIAL APPROACH"}', 2, 1),
('services', 'Curated Interior Solutions', 'From residential retreats to inspiring workplaces, our work balances aesthetics, comfort, and enduring craft.', '', '{"limit":6}', 3, 1),
('featured_projects', 'Selected Design Works', 'An editorial collection of spatial concepts, material investigations, and interior studies.', '', '{"limit":4}', 4, 1),
('philosophy', 'Every Detail Has a Purpose.', 'We believe that exceptional interiors are never accidental. They are shaped by the interplay of natural light, tactile authenticity, spatial clarity, and timeless proportion.', '', '{"image":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=85"}', 5, 1),
('design_process', 'Our Thoughtful Process', 'A structured, transparent pathway from initial discovery to spatial completion.', '', '', 6, 1),
('materials_gallery', 'Materials & Tactile Palette', 'Sensory finishes and architectural compositions that ground each space in natural luxury.', '', '', 7, 1),
('testimonials', 'Client Reflections', 'Reflections on spatial transformations and collaborative design journeys.', '', '{"show_demo_label":true}', 8, 1),
('final_cta', 'Let\'s Create a Space That Feels Right.', 'Tell us about your vision, and let\'s explore the possibilities.', '', '{"image":"https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=2000&q=85","cta_text":"START YOUR PROJECT","cta_url":"/contact"}', 9, 1)
INSERT INTO services (title, slug, category, short_description, full_description, featured_image, features_json, sort_order, is_published, seo_title, seo_description) VALUES
('Residential Interior Design', 'residential-interiors', 'Residential', 'Comprehensive design for entire homes, apartments, and private sanctuaries tailored to your rhythm of life.', 'Our residential interior design service takes an end-to-end editorial approach to creating living spaces that are both deeply functional and visually inspiring. We work closely with you from initial floor plan analysis to bespoke joinery, acoustic balance, and custom lighting layers.', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=85', '["Full space spatial planning","Custom millwork and built-ins","Architectural lighting scheme","Complete color and material curation","Art and accessories direction"]', 1, 1, 'Residential Interior Design — WROP Interior', 'Bespoke residential interior design services creating calm, elevated spaces for modern living.'),
('Living Room Design', 'living-room-design', 'Residential', 'Harmonious gathering spaces balancing warmth, focal architectural balance, and generous comfort.', 'The living room is the emotional anchor of the home. We compose environments where conversation flows effortlessly, featuring sculptural seating, textural acoustic wall finishes, concealed storage, and curated ambient illumination.', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=85', '["Ergonomic conversational seating arrangements","Custom TV units & fireplace surrounds","Curated tactile rugs & drapery","Zoned mood lighting systems"]', 2, 1, 'Living Room Design — WROP Interior', 'Sculptural, warm, and architectural living room interiors.'),
('Modular Kitchen Design', 'modular-kitchen-design', 'Kitchen & Bath', 'Architectural culinary studios uniting precision German/European hardware with timeless natural surfaces.', 'A kitchen must be as delightful to work within as it is to behold. We design ergonomic work triangles, integrated concealed appliances, quartz and quartzite countertops, and bespoke fluted wood cabinetry.', 'https://images.unsplash.com/photo-1556911220-e15b29be8c8f?auto=format&fit=crop&w=1200&q=85', '["Ergonomic workflow optimization","Integrated appliance planning","Stone countertop and backsplash specification","Hidden pantry and smart storage solutions"]', 3, 1, 'Modular Kitchen Design — WROP Interior', 'Precision engineered, warm minimalist kitchen design solutions.'),
('Bedroom & Sanctuary Design', 'bedroom-design', 'Residential', 'Restful sanctuaries engineered with tactile textiles, acoustic warmth, and serene lighting.', 'Our bedroom concepts prioritize peaceful decompression. Through calibrated acoustic layering, upholstered headboard walls, indirect architectural coves, and serene color psychology, we create spaces of deep rest.', 'https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1200&q=85', '["Acoustic fabric wall panels","Custom built-in headboards & floating nightstands","Blackout automated drapery integration","Calibrated circadian warm lighting"]', 4, 1, 'Bespoke Bedroom Design — WROP Interior', 'Restful, architectural bedrooms tailored for calm and tranquility.'),
('Wardrobe & Dressing Suites', 'wardrobe-design', 'Joinery', 'Walk-in closets and bespoke wardrobe systems finished with fine veneer, bronze detailing, and tinted glass.', 'We transform dressing areas into boutique personal galleries. Featuring velvet-lined jewelry drawers, perimeter LED channel illumination, and integrated climate-balanced ventilation.', 'https://images.unsplash.com/photo-1558997519-83ea9252def8?auto=format&fit=crop&w=1200&q=85', '["Bespoke walk-in dressing suites","Integrated concealed lighting","Fluted glass and aluminum frames","Custom leather and brass drawer organizers"]', 5, 1, 'Custom Wardrobe Design — WROP Interior', 'Luxury walk-in closets and bespoke millwork storage systems.'),
('Commercial & Office Interiors', 'commercial-interiors', 'Commercial', 'Forward-thinking corporate headquarters, boutique retail spaces, and creative studio environments.', 'Commercial design that reinforces brand identity while fostering collaboration and deep focus. We merge high-durability commercial materials with residential warmth to create environments people look forward to working in.', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=85', '["Activity-based spatial zoning","Acoustic ceiling baffles and timber walls","Branded reception and client presentation suites","Commercial biophilic integrations"]', 6, 1, 'Commercial & Workplace Interiors — WROP Interior', 'Sophisticated office and commercial space design that elevates performance.'),
('Space Planning & Architectural Layouts', 'space-planning', 'Architecture', 'Rigorous spatial circulation analysis to unlock the true potential of your floor plan.', 'Before selecting a single textile, true luxury begins with proportion. We evaluate structural sightlines, natural daylight penetration, and micro-movements to craft intuitive flow throughout the property.', 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=1200&q=85', '["Detailed 2D circulation flow layouts","Daylight penetration and shadow study","Demolition and partition reconfigurations","Zoned privacy transitions"]', 7, 1, 'Space Planning & Layout Design — WROP Interior', 'Intelligent architectural space planning and floor plan optimization.'),
('Furniture & Material Selection', 'material-selection', 'Curation', 'Bespoke procurement of artisan furniture, rare stones, tactile textiles, and architectural hardware.', 'We curate materials that age gracefully over decades. From honed Travertine and brushed Fior di Bosco marble to Belgian linen and oiled white oak, our material palettes impart authentic character.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=1200&q=85', '["Physical material sample boards","Trade-only furniture sourcing","Custom artisan commissions","Sustainable and non-toxic finish verification"]', 8, 1, 'Material Selection & Furniture Curation — WROP Interior', 'Tactile material curation and bespoke designer furniture sourcing.')
INSERT INTO projects (title, slug, category, location, is_demo, short_description, full_description, concept, materials_finishes, scope, featured_image, gallery_json, is_featured, sort_order, is_published, seo_title, seo_description) VALUES
('The Travertine Residence', 'the-travertine-residence', 'Residential', 'Concept Study', 1, 'A serene residential sanctuary grounded in warm limestone, fluted timber, and diffused natural light.', 'The Travertine Residence explores the convergence of architectural minimalism and tactile comfort. Conceived as a peaceful haven away from the metropolitan bustle, the design utilizes monolithic stone forms softened by billowing linen drapery and bespoke dark oak cabinetry.', 'Monolithic serenity through natural stone geometry and filtered daylight.', 'Honed Roman Travertine, American White Oak, Belgian Natural Linen, Brushed Bronze Hardware', 'Full interior architecture, spatial replanning, bespoke millwork, lighting specification', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1556911220-e15b29be8c8f?auto=format&fit=crop&w=1200&q=85"]', 1, 1, 1, 'The Travertine Residence — WROP Interior Concept Study', 'A concept study exploring serene residential spaces with travertine and warm wood.'),
('Atelier V — Creative Studio', 'atelier-v-studio', 'Commercial', 'Design Exploration', 1, 'An open-concept creative studio balancing collaborative energy with focused architectural alcoves.', 'Designed for a high-pace multidisciplinary creative agency, Atelier V incorporates acoustic wool felt dividers, solid smoked oak communal benches, and warm architectural track lighting to provide an elevated work environment.', 'Biophilic productivity and acoustic harmony in an industrial volume.', 'Smoked European Oak, Recycled Wool Acoustic Felt, Textured Clay Plaster, Matte Black Steel', 'Commercial workplace zoning, acoustic consultation, bespoke conference tables', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=1200&q=85"]', 1, 2, 1, 'Atelier V Creative Studio — WROP Interior Design Concept', 'An inspiring commercial workplace concept balancing focus and collaboration.'),
('Komorebi Penthouse', 'komorebi-penthouse', 'Residential', 'Demonstration Showcase', 1, 'A dual-level penthouse celebrating the poetry of sunlight filtering through timber lattice screens.', 'Taking inspiration from Japanese and Scandinavian design sensibilities (Japandi), this penthouse focuses on low-slung furnishings, shoji-inspired sliding architectural partitions, and a continuous Microcement floor palette.', 'Warm Japandi minimalism celebrating shadow and light.', 'Hinoki and Ash Wood, Microcement, Hand-loomed Silk Wool Rugs, Matte Ceramic Tiles', 'Dual-level residential interior design, custom room dividers, curated furnishings', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1584622650111-993a426fbf0a?auto=format&fit=crop&w=1200&q=85"]', 1, 3, 1, 'Komorebi Penthouse — WROP Interior Concept Study', 'A dual-level penthouse celebrating filtered natural light and organic materials.'),
('The Clay & Brass Sanctuary', 'clay-and-brass-sanctuary', 'Residential', 'Demonstration Concept', 1, 'An intimate urban apartment centered around earthy lime-washed walls and patinated unlacquered brass.', 'In this residential study, textured clay plaster surfaces absorb harsh daylight, creating a soft cocooning ambiance. Custom brass details throughout the joinery will naturally patina over time, gaining character and depth.', 'Sensory richness through honest, unadorned materials that age gracefully.', 'Hand-applied Terracotta Clay Plaster, Unlacquered Brass, Calacatta Viola Marble, Oiled Walnut', 'Full spatial remodel, bespoke kitchen island, custom bathroom vanity and finishes', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=85', '["https://images.unsplash.com/photo-1558997519-83ea9252def8?auto=format&fit=crop&w=1200&q=85","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=85"]', 1, 4, 1, 'The Clay & Brass Sanctuary — WROP Interior Showcase', 'Warm clay plaster, unlacquered brass, and rich tactile interiors.')
INSERT INTO journal_articles (title, slug, category, excerpt, content, featured_image, read_time, is_published, published_at, seo_title, seo_description) VALUES
('The Architecture of Silence: Designing for Sensory Calm', 'the-architecture-of-silence', 'Design Theory', 'How acoustic layering, tactile surfaces, and restrained palettes create sanctuaries in bustling metropolitan environments.', 'In modern interior design, visual minimalism often commands the conversation. Yet the true measure of a peaceful home is acoustic and sensory. When we enter a space where sound doesn\'t bounce harshly off polished concrete and reflective glass, our nervous system immediately settles.\n\nAt WROP Interior, we achieve sensory calm by weaving acoustic dampening into structural elements: timber slat ceilings backed by recycled acoustic felt, lime plaster walls that softly diffuse sound waves, and double-lined linen drapery that frames views without rigidity.', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=85', '4 min read', 1, CURRENT_TIMESTAMP, 'The Architecture of Silence — WROP Interior Journal', 'Exploring how acoustic design and organic materiality create sensory peace in modern homes.'),
('Natural Light as a Building Material', 'natural-light-as-a-building-material', 'Lighting', 'Understanding how sunlight shifts throughout the day enables us to choose materials that transform from morning clarity to evening intimacy.', 'Light is not merely illumination; it is the most dynamic finish in any interior. Morning eastern sunlight carries cool blue undertones that accentuate stone and polished nickel. Late afternoon western rays cast long, amber shadows that bring alive textured clay plaster and rich walnut timber.\n\nDesigning with daylight requires mapping the sun\'s seasonal transit across floor plans. By placing reflective light shelves and sheer linen treatments strategically, we channel natural radiance into the deepest corridors of the home.', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=85', '5 min read', 1, CURRENT_TIMESTAMP, 'Natural Light as a Building Material — WROP Interior Journal', 'How interior architects orchestrate natural sunlight to transform interior spaces.'),
('The Beauty of Imperfection: Honest Materials That Age', 'beauty-of-imperfection-materials', 'Materials', 'Why we advocate for unlacquered brass, open-grain oak, and honed limestone that tell stories over decades.', 'Modern synthetic surfaces promise perpetual perfection: stain-proof quartz, scratch-resistant laminates, sealed metals that never tarnish. Yet this artificial stillness can make spaces feel detached from life.\n\nLiving with authentic natural materials offers a richer dialogue. Unlacquered brass records the touch of family hands. Honed marble softens with use. Solid timber absorbs the climate and breathes. Choosing honest materials means choosing a home that grows more beautiful with each passing year.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=1200&q=85', '6 min read', 1, CURRENT_TIMESTAMP, 'The Beauty of Honest Materials — WROP Interior Journal', 'Celebrating materials that develop depth, character, and patina over time.')
