-- WROP Interior Seed Data

-- 1. Initial Administrative Users
ON DUPLICATE KEY UPDATE updated_at = CURRENT_TIMESTAMP;

-- 2. Site Settings
ON DUPLICATE KEY UPDATE `value` = VALUES(`value`);

-- 3. System Settings
ON DUPLICATE KEY UPDATE `value` = VALUES(`value`);

-- 4. Homepage Sections
ON DUPLICATE KEY UPDATE title = VALUES(title), subtitle = VALUES(subtitle), content = VALUES(content), settings_json = VALUES(settings_json);

-- 5. Services
ON DUPLICATE KEY UPDATE title = VALUES(title), short_description = VALUES(short_description);

-- 6. Sample Projects (Clearly labeled as demonstration design concepts)
ON DUPLICATE KEY UPDATE title = VALUES(title), short_description = VALUES(short_description);

-- 7. Journal Articles
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt);
